        return { ok: true, text, raw: r }; // no costUsd: ChatGPT-account auth reports tokens, not dollars
      }
      return { ok: false, error: failure || `exit=${r.code} ${r.stderr.slice(0, 200)}`, raw: r };
    },
  };
}

