--- test/adapters.test.ts
// Adapter classifier tests — run against fake CLIs (test/fakes/*) that replay
// envelopes captured from REAL runs (research/canary-results.md + the
// 2026-06-11 budget-exceeded canary). The fakes shadow the real binaries via PATH.

import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { tmpdir } from "node:os";
import { claudeAdapter, agyAdapter, codexAdapter } from "../src/adapters.ts";

const here = dirname(fileURLToPath(import.meta.url));
const fixtures = join(here, "fixtures");
process.env.PATH = `${join(here, "fakes")}:${process.env.PATH}`;

const cwd = tmpdir();

beforeEach(() => {
  for (const k of Object.keys(process.env)) if (k.startsWith("FAKE_")) delete process.env[k];
});

// --- claude: JSON envelope ------------------------------------------------------------

test("claude: success envelope → ok with text and cost", async () => {
  process.env.FAKE_STDOUT_FILE = join(fixtures, "claude-success.json");
  const r = await claudeAdapter().run("ping", cwd);
  assert.equal(r.ok, true);
  assert.equal(r.ok && r.text, "pong");
  assert.equal(r.ok && r.costUsd, 0.10388775);
});

test("claude: budget-exceeded envelope (no `result` string) → error from `errors` array", async () => {
  process.env.FAKE_STDOUT_FILE = join(fixtures, "claude-budget-error.json");
  process.env.FAKE_EXIT = "1";
  const r = await claudeAdapter().run("ping", cwd);
  assert.equal(r.ok, false);
  assert.match(!r.ok ? r.error : "", /Reached maximum budget/);
});

test("claude: REGRESSION — subtype lies on error; classify on is_error", async () => {
  process.env.FAKE_STDOUT_FILE = join(fixtures, "claude-model-error.json");
  process.env.FAKE_EXIT = "1";
  const r = await claudeAdapter().run("ping", cwd);
  assert.equal(r.ok, false); // subtype says "success" — is_error must win
  assert.match(!r.ok ? r.error : "", /issue with the selected model/);
});

test("claude: non-JSON stdout → error with exit code", async () => {
  process.env.FAKE_STDERR = "boom";
  process.env.FAKE_EXIT = "1";
  const r = await claudeAdapter().run("ping", cwd);
  assert.equal(r.ok, false);
  assert.match(!r.ok ? r.error : "", /exit=1/);
});

test("claude: exit 126 (stale shim) → setup hint, not a cryptic error", async () => {
  process.env.FAKE_EXIT = "126";
  const r = await claudeAdapter().run("ping", cwd);
  assert.equal(r.ok, false);
  assert.match(!r.ok ? r.error : "", /asdf shims/);
});

// --- agy: text-only -------------------------------------------------------------------

test("agy: trimmed stdout is the answer", async () => {
  process.env.FAKE_STDOUT_FILE = join(fixtures, "claude-success.json"); // any text payload works
  const r = await agyAdapter().run("ping", cwd);
  assert.equal(r.ok, true);
});

test("agy: empty stdout → failure even on exit 0", async () => {
  const r = await agyAdapter().run("ping", cwd);
  assert.equal(r.ok, false);
});

test("agy: timeout kills the run and reports it", async () => {
  process.env.FAKE_SLEEP = "2";
  const r = await agyAdapter("Gemini 3.5 Flash (High)", { timeoutMs: 200 }).run("ping", cwd);
  assert.equal(r.ok, false);
  assert.equal(!r.ok && r.error, "timeout");
});

// --- codex: JSONL ----------------------------------------------------------------------

test("codex: success JSONL → LAST agent_message wins", async () => {
  process.env.FAKE_STDOUT_FILE = join(fixtures, "codex-success.jsonl");
  const r = await codexAdapter().run("ping", cwd);
  assert.equal(r.ok, true);
  assert.equal(r.ok && r.text, "pong"); // not "intermediate thought"
});

test("codex: turn.failed → failure with the event's message", async () => {
  process.env.FAKE_STDOUT_FILE = join(fixtures, "codex-turn-failed.jsonl");
  process.env.FAKE_EXIT = "1";
  const r = await codexAdapter().run("ping", cwd);
  assert.equal(r.ok, false);
  assert.match(!r.ok ? r.error : "", /not supported/);
});

test("codex: exit 0 but no turn.completed → failure (incomplete stream)", async () => {
  process.env.FAKE_STDOUT_FILE = join(fixtures, "codex-turn-failed.jsonl");
  const r = await codexAdapter().run("ping", cwd);
  assert.equal(r.ok, false);
});

test("codex: custom bin override is used", async () => {
  process.env.FAKE_STDOUT_FILE = join(fixtures, "codex-success.jsonl");
  const r = await codexAdapter(undefined, { bin: join(here, "fakes", "codex") }).run("ping", cwd);
  assert.equal(r.ok, true);
});
--- test/config.test.ts
// Config parser tests — the minimal YAML subset behind --config debate.yaml.

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { parseDebateConfig } from "../src/config.ts";

const here = dirname(fileURLToPath(import.meta.url));

test("parses the shipped example config", async () => {
  const text = await readFile(join(here, "..", "examples", "debate.yaml"), "utf8");
  const cfg = parseDebateConfig(text);
  assert.equal(cfg.rounds, 1);
  assert.equal(cfg.timeoutMinutes, 10);
  assert.equal(cfg.repo, undefined); // commented out
  assert.equal(cfg.participants?.length, 2);
  assert.deepEqual(cfg.participants?.[0], { adapter: "claude", model: "sonnet", maxBudgetUsd: 2 });
  assert.equal(cfg.participants?.[1].adapter, "codex");
  assert.equal(cfg.participants?.[1].bin, "/opt/homebrew/bin/codex");
});

test("models with spaces and parens survive (agy model names)", () => {
  const cfg = parseDebateConfig(
    "participants:\n  - adapter: agy\n    model: Gemini 3.5 Flash (High)\n  - adapter: claude\n",
  );
  assert.equal(cfg.participants?.[0].model, "Gemini 3.5 Flash (High)");
});

test("quoted values are unquoted", () => {
  const cfg = parseDebateConfig('repo: "/tmp/my repo"\n');
  assert.equal(cfg.repo, "/tmp/my repo");
});

test("rejects unknown top-level keys with the line number", () => {
  assert.throws(() => parseDebateConfig("round: 2\n"), /line 1: unknown key "round"/);
});

test("rejects unknown participant keys", () => {
  assert.throws(
    () => parseDebateConfig("participants:\n  - adapter: claude\n    budget: 2\n"),
    /unknown participant key "budget"/,
  );
});

test("rejects a single-participant lineup", () => {
  assert.throws(() => parseDebateConfig("participants:\n  - adapter: claude\n"), /at least 2 participants/);
});

test("rejects unknown adapters", () => {
  assert.throws(
    () => parseDebateConfig("participants:\n  - adapter: cursor\n  - adapter: claude\n"),
    /adapter: claude \| agy \| codex/,
  );
});

test("rejects non-numeric numeric keys and non-integer rounds", () => {
  assert.throws(() => parseDebateConfig("rounds: many\n"), /must be a number/);
  assert.throws(() => parseDebateConfig("rounds: 1.5\n"), /non-negative integer/);
});

test("rejects nested structures it cannot represent", () => {
  assert.throws(() => parseDebateConfig("participants:\n  - adapter: claude\n      deep:\n        nope: 1\n"), /line/);
});
--- test/debate.test.ts
// Orchestration tests — fake in-process participants (no spawning), plus a REAL
// git repo in a temp dir to verify the read-only worktree isolation invariant.

import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, writeFile, readFile, rm } from "node:fs/promises";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { runDebate } from "../src/debate.ts";
import type { Participant, AgentResult } from "../src/adapters.ts";

const execFileAsync = promisify(execFile);

function fake(id: string, vendor: string, run: Participant["run"]): Participant {
  return { id, vendor, display: id, run };
}
const ok = (text: string): AgentResult => ({ ok: true, text, costUsd: 0.5 });
const fail = (error: string): AgentResult => ({ ok: false, error });

test("abort: <2 successful proposals ends the debate before any reaction round", async () => {
  let reactions = 0;
  const a = fake("a", "v1", async (prompt) => {
    if (prompt.includes("debate so far")) reactions++;
    return ok("proposal A");
  });
  const b = fake("b", "v2", async () => fail("timeout"));
  const out = await runDebate("task", [a, b], 3);
  assert.ok(out.aborted);
  assert.match(out.aborted!, /only 1\/2 proposals succeeded/);
  assert.match(out.transcript, /Debate aborted/);
  assert.equal(reactions, 0);
});

test("abort: both proposals failing lists both failures", async () => {
  const a = fake("a", "v1", async () => fail("budget"));
  const b = fake("b", "v2", async () => fail("timeout"));
  const out = await runDebate("task", [a, b], 1);
  assert.ok(out.aborted);
  assert.match(out.aborted!, /a: budget/);
  assert.match(out.aborted!, /b: timeout/);
});

test("reaction context is clean: proposals included, cost footnotes excluded", async () => {
  const seen: string[] = [];
  const a = fake("a", "v1", async (prompt) => {
    if (prompt.includes("debate so far")) seen.push(prompt);
    return ok("proposal A says X");
  });
  const b = fake("b", "v2", async () => ok("proposal B says Y"));
  const out = await runDebate("task", [a, b], 1);
  assert.equal(out.aborted, undefined);
  assert.equal(seen.length, 1);
  assert.match(seen[0], /proposal A says X/);
  assert.match(seen[0], /proposal B says Y/);
  assert.doesNotMatch(seen[0], /cost:/);              // prompt hygiene
  assert.match(out.transcript, /cost: \$0\.5000/);    // …but the artifact keeps cost
  assert.equal(out.turns.length, 4);                  // 2 proposals + 2 reactions
});

test("worktree isolation: agents run in a throwaway worktree, never the real checkout", async () => {
  // a real git repo with one committed file
  const repo = await mkdtemp(join(tmpdir(), "disputatio-test-repo-"));
  const git = (...args: string[]) => execFileAsync("git", ["-C", repo, ...args]);
  await git("init", "-q");
  await git("config", "user.email", "test@test");
  await git("config", "user.name", "test");
  await writeFile(join(repo, "evidence.txt"), "committed evidence");
  await git("add", ".");
  await git("commit", "-q", "-m", "init");

  const cwds: string[] = [];
  const misbehave = fake("m", "v1", async (_prompt, cwd) => {
    cwds.push(cwd);
    const evidence = await readFile(join(cwd, "evidence.txt"), "utf8"); // tracked files ARE visible
    await writeFile(join(cwd, "stray-write.log"), "agent wrote here");  // simulated misbehavior
    return ok(evidence);
  });
  const second = fake("s", "v2", async (_prompt, cwd) => {
    cwds.push(cwd);
    return ok("fine");
  });

  const out = await runDebate("task", [misbehave, second], 0, repo);
  assert.equal(out.aborted, undefined);
  assert.match(out.transcript, /committed evidence/);

  for (const cwd of cwds) assert.notEqual(cwd, repo);              // never the real checkout
  const status = await git("status", "--porcelain");
  assert.equal(status.stdout.trim(), "");                          // stray write didn't touch the repo
  const wt = await git("worktree", "list");
  assert.equal(wt.stdout.trim().split("\n").length, 1);            // all worktrees cleaned up

  await rm(repo, { recursive: true, force: true });
});
