    child.stdout.on("data", (d) => { stdout += d.toString(); });
    child.stderr.on("data", (d) => { stderr += d.toString(); });
    child.on("error", (e) => {
      stderr = String(e);
      if (!timedOut) finish(null);
    });
    child.on("close", (code) => {
      if (!timedOut) finish(code);
    });
  });
}

